import contextlib
import io
import json
import os
import subprocess
import sys
import tempfile
import unittest
from unittest import mock

from pennywise import cli

SAMPLE = """# household, March
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop

2024-03-05 Rent -900
"""


def run(*argv, stdin=None):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        if stdin is None:
            code = cli.main(list(argv))
        else:
            with mock.patch("sys.stdin", io.StringIO(stdin)):
                code = cli.main(list(argv))
    return code, out.getvalue(), err.getvalue()


class CliCase(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.dir = tmp.name
        self.path = os.path.join(self.dir, "house.txt")
        self.write(SAMPLE)

    def write(self, text, path=None):
        with open(path or self.path, "w", encoding="utf-8", newline="") as f:
            f.write(text)

    def read(self, path=None):
        with open(path or self.path, "rb") as f:
            return f.read()


class ReadCommandTests(CliCase):
    def test_balance(self):
            (0, 'date,category,amount,note\n2024-03-01,a,-2.00,\n2024-03-05,b,1.00,"hello, ""world"""\n', ""),
        )
        self.assertEqual(run("export", self.path, "--format", "csv")[1], run("export", self.path)[1])

    def test_stdin(self):
        for cmd in ("balance", "summary", "list", "export"):
            code, out, _ = run(cmd, "-", stdin=SAMPLE)
            self.assertEqual(code, 0, cmd)
            self.assertEqual(out, run(cmd, self.path)[1], cmd)

    def test_utf8(self):
        self.write("2024-03-01 café 1 crème brûlée\n")
        self.assertEqual(run("list", self.path)[1], "2024-03-01 café 1.00 crème brûlée\n")


class ErrorTests(CliCase):
            "2024-03-02 groceries -42.50 weekly shop\n2024-03-02 groceries -3.00 milk\n",
        )


class SubprocessTests(CliCase):
    def test_python_dash_m(self):
        env = dict(os.environ)
        src = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "src")
        env["PYTHONPATH"] = src + os.pathsep + env.get("PYTHONPATH", "")
        res = subprocess.run(
            [sys.executable, "-m", "pennywise", "balance", "-"],
            input=SAMPLE, capture_output=True, text=True, env=env,
        )
        self.assertEqual((res.returncode, res.stdout, res.stderr), (0, "1557.50\n", ""))
        res = subprocess.run(
            [sys.executable, "-m", "pennywise"], capture_output=True, text=True, env=env
        )
        self.assertEqual((res.returncode, res.stdout), (2, ""))


class BrokenPipeTests(CliCase):
    """A reader that closes early must not make pennywise look like it failed."""

    def setUp(self):
        super().setUp()
        self.env = dict(os.environ)
        src = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "src")
        self.env["PYTHONPATH"] = src + os.pathsep + self.env.get("PYTHONPATH", "")
        self.big = os.path.join(self.dir, "big.txt")
        with open(self.big, "w") as f:
            for i in range(20000):
                f.write("2024-03-%02d cat%d -1.00 note number %d\n" % (i % 28 + 1, i, i))

    def pipe_into_early_reader(self, *argv, stdin=None):
        """Run pennywise with stdout piped to a reader that reads 1 byte and exits."""
        proc = subprocess.Popen(
            [sys.executable, "-m", "pennywise", *argv],
            stdin=stdin, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=self.env,
        )
        proc.stdout.read(1)
        proc.stdout.close()
        err = proc.stderr.read()
        return proc.wait(timeout=60), err

    def test_list_closed_pipe(self):
        self.assertEqual(self.pipe_into_early_reader("list", self.big), (0, b""))

    def test_list_json_closed_pipe(self):
        self.assertEqual(self.pipe_into_early_reader("list", self.big, "--json"), (0, b""))

    def test_export_closed_pipe(self):
        self.assertEqual(self.pipe_into_early_reader("export", self.big), (0, b""))

    def test_summary_closed_pipe(self):
        self.assertEqual(self.pipe_into_early_reader("summary", self.big), (0, b""))

    def test_stdin_closed_pipe(self):
        with open(self.big, "rb") as f:
            self.assertEqual(self.pipe_into_early_reader("list", "-", stdin=f), (0, b""))

    def test_silence_stdout_without_fd(self):
        with contextlib.redirect_stdout(io.StringIO()):
            cli._silence_stdout()  # no fileno: must not raise


if __name__ == "__main__":
    unittest.main()

